37		/**
38		 * Migrate backwpup global settings to a single option data
39		 *
40		 * @return void
41		 */
42		public function backwpup_migrate_options() {
43			// If this migrate is done, bail early.
44			if ( get_option( 'backwpup_settings_migration_done' ) ) {
45				return;
46			}
47	
48			$option_keys = [
49				'backwpup_archiveformat',
50				'backwpup_version',
51				'backwpup_cfg_loglevel',
52				'backwpup_cfg_logfolder',
53				'backwpup_previous_version',
54				'backwpup_cfg_hash',
55				'backwpup_activation_time',
56				'backwpup_cfg_showadminbar',
57				'backwpup_cfg_showfoldersize',
58				'backwpup_cfg_keepplugindata',
59				'backwpup_cfg_jobmaxexecutiontime',
60				'backwpup_cfg_jobstepretry',
61				'backwpup_cfg_jobrunauthkey',
62				'backwpup_cfg_jobwaittimems',
63			];
64	
65			foreach ( $option_keys as $key ) {
66				$value = get_option( $key );
67				if ( false !== $value ) {
68					$this->options->set( $key, $value );
69				}
70			}
71	
72			// Set to true to avoid running multiple times.
73			update_option( 'backwpup_settings_migration_done', 1 );
74		}
75	}
