71		public function prepare_items() {
72			$per_page = $this->get_items_per_page( 'backwpupbackups_per_page' );
73			if ( empty( $per_page ) || $per_page < 1 ) {
74				$per_page = 20;
75			}
76	
77			$jobdest               = '';
78			$jobdest_top_button    = filter_input( INPUT_GET, 'jobdets-button-top', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
79			$jobdest_bottom_button = filter_input( INPUT_GET, 'jobdets-button-bottom', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
80	
81			if ( $jobdest_top_button ) {
82				$jobdest = filter_input( INPUT_GET, 'jobdest-top', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
83			}
84			if ( $jobdest_bottom_button ) {
85				$jobdest = filter_input( INPUT_GET, 'jobdest-bottom', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
86			}
87			$jobdest = $jobdest ? sanitize_text_field( $jobdest ) : '';
88	
89			if ( empty( $jobdest ) ) {
90				$jobdests = $this->get_destinations_list();
91				if ( empty( $jobdests ) ) {
92					$jobdests = [ '_' ];
93				}
94				$jobdest                    = $jobdests[0];
95				$_GET['jobdest-top']        = $jobdests[0];
96				$_GET['jobdets-button-top'] = 'empty';
97			}
98	
99			[$this->jobid, $this->dest] = explode( '_', (string) $jobdest );
100	
101			if ( ! empty( $this->destinations[ $this->dest ]['class'] ) ) {
102				/**
103				 * Destination handler instance.
104				 *
105				 * @var BackWPup_Destinations $dest_object
106				 */
107				$dest_object = BackWPup::get_destination( $this->dest );
108				$this->items = $dest_object->file_get_list( $jobdest );
109			}
110	
111			if ( ! $this->items ) {
112				$this->items = '';
113	
114				return;
115			}
116	
117			// Sorting.
118			$order   = 'desc';
119			$orderby = 'time';
120			$nonce   = $this->get_list_nonce();
121			if ( $nonce && wp_verify_nonce( $nonce, self::LIST_NONCE_ACTION ) ) {
122				$order = filter_input( INPUT_GET, 'order', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
123				if ( null === $order && isset( $_GET['order'] ) ) {
124					$order = sanitize_text_field( wp_unslash( $_GET['order'] ) );
125				} else {
126					$order = $order ? sanitize_text_field( $order ) : '';
127				}
128				$order = $order ? sanitize_key( $order ) : 'desc';
129				$order = strtolower( $order );
130				$order = in_array( $order, [ 'asc', 'desc' ], true ) ? $order : 'desc';
131	
132				$orderby = filter_input( INPUT_GET, 'orderby', FILTER_SANITIZE_FULL_SPECIAL_CHARS );
133				if ( null === $orderby && isset( $_GET['orderby'] ) ) {
134					$orderby = sanitize_text_field( wp_unslash( $_GET['orderby'] ) );
135				} else {
136					$orderby = $orderby ? sanitize_text_field( $orderby ) : '';
137				}
138				$orderby = $orderby ? sanitize_key( $orderby ) : 'time';
139				$orderby = strtolower( $orderby );
140				$orderby = in_array( $orderby, [ 'time', 'file', 'folder', 'size' ], true ) ? $orderby : 'time';
141			}
142			$tmp = [];
143	
144			if ( 'time' === $orderby ) {
145				if ( 'asc' === $order ) {
146					foreach ( $this->items as &$ma ) {
147						$tmp[] = &$ma['time'];
148					}
149					array_multisort( $tmp, SORT_ASC, $this->items );
150				} else {
151					foreach ( $this->items as &$ma ) {
152						$tmp[] = &$ma['time'];
153					}
154					array_multisort( $tmp, SORT_DESC, $this->items );
155				}
156			} elseif ( 'file' === $orderby ) {
157				if ( 'asc' === $order ) {
158					foreach ( $this->items as &$ma ) {
159						$tmp[] = &$ma['filename'];
160					}
161					array_multisort( $tmp, SORT_ASC, $this->items );
162				} else {
163					foreach ( $this->items as &$ma ) {
164						$tmp[] = &$ma['filename'];
165					}
166					array_multisort( $tmp, SORT_DESC, $this->items );
167				}
168			} elseif ( 'folder' === $orderby ) {
169				if ( 'asc' === $order ) {
170					foreach ( $this->items as &$ma ) {
171						$tmp[] = &$ma['folder'];
172					}
173					array_multisort( $tmp, SORT_ASC, $this->items );
174				} else {
175					foreach ( $this->items as &$ma ) {
176						$tmp[] = &$ma['folder'];
177					}
178					array_multisort( $tmp, SORT_DESC, $this->items );
179				}
180			} elseif ( 'size' === $orderby ) {
181				if ( 'asc' === $order ) {
182					foreach ( $this->items as &$ma ) {
183						$tmp[] = &$ma['filesize'];
184					}
185					array_multisort( $tmp, SORT_ASC, $this->items );
186				} else {
187					foreach ( $this->items as &$ma ) {
188						$tmp[] = &$ma['filesize'];
189					}
190					array_multisort( $tmp, SORT_DESC, $this->items );
191				}
192			}
193	
194			$this->set_pagination_args(
195				[
196					'total_items' => count( $this->items ),
197					'per_page'    => $per_page,
198					'jobdest'     => $jobdest,
199					'orderby'     => $orderby,
200					'order'       => $order,
201				]
202				);
203	
204			// Only display items on page.
205			$start = intval( ( $this->get_pagenum() - 1 ) * $per_page );
206			$end   = $start + $per_page;
207			if ( $end > count( $this->items ) ) {
208				$end = count( $this->items );
209			}
210	
211			$i           = -1;
212			$paged_items = [];
213	
214			foreach ( $this->items as $item ) {
215				++$i;
216				if ( $i < $start ) {
217					continue;
218				}
219				if ( $i >= $end ) {
220					break;
221				}
222				$paged_items[] = $item;
223			}
224	
225			$this->items = $paged_items;
226		}
