/**
 * Enqueue Styles.
 */
public function admin_enqueue_scripts() {
	if ( ! current_user_can( 'backwpup' ) ) {
		return;
	}
	$is_debug = ( defined( 'SCRIPT_DEBUG' ) && SCRIPT_DEBUG );

	wp_enqueue_style(
		'backwpup_pro',
		BackWPup::get_plugin_data( 'URL' ) . '/assets/css/pro.min.css',
		[],
		( $is_debug ? BackWPup::get_plugin_data( 'Version' ) : time() ),
		'screen'
	);
}

/**
 * Add extra Destinations or overwrite.
 *
 * @param array $destinations The destinations array.
 *
 * @return array The filtered destination array
 */
public function register_destination( $destinations ) {
	// Add/overwrite BackWPup Destinations to folder.
	$destinations['FOLDER']['class']    = \BackWPup_Pro_Destination_Folder::class;
	$destinations['FOLDER']['can_sync'] = true;
	// Backup to ftp.
	$destinations['FTP']['class'] = \BackWPup_Pro_Destination_Ftp::class;
	// Backup to dropbox.
	$destinations['DROPBOX']['class']    = \BackWPup_Pro_Destination_Dropbox::class;
	$destinations['DROPBOX']['can_sync'] = true;
	// Backup to S3.
	$destinations['S3']['class']    = \BackWPup_Pro_Destination_S3::class;
	$destinations['S3']['can_sync'] = true;
	// Backup to MS Azure.
	$destinations['MSAZURE']['class']    = \BackWPup_Pro_Destination_MSAzure::class;
	$destinations['MSAZURE']['can_sync'] = true;

