.progressbar{margin-top:10px;height:auto;background:#f6f6f6 url("../../assets/images/progressbarhg.jpg")}
---
.progressbar .bwpu-progress{background-color:#1d94cf;color:#fff;padding:5px 0;text-align:center}
---
#documentation_content p{font-size:14px;line-height:20px;color:#333}
---
#documentation_content h3{padding:7px 0;font-size:22px}
---
#documentation_content h4{padding:7px 0;font-size:18px}
---
#wpfooter #footer-left,#wpfooter #footer-right{overflow:hidden}
---
#wpfooter #footer-left #footer-thankyou{clear:both;display:block;padding-top:.5em}
---
#wpfooter #footer-left .backwpup-get-pro{display:inline-block;line-height:25px}
---
#wpfooter #footer-upgrade .backwpup-update-footer{display:block;line-height:25px}
---
#wpfooter .wpmedia_logo{display:block;margin-right:15px;margin-top:5px;line-height:25px;height:25px;width:86px;text-decoration:none}
---
.drag-drop-area{background:#fafafa;border:4px dashed #ddd;color:#aaa;padding:60px 0;text-align:center;width:100%}
---
.drag-drop-area .drop-text{font-size:1rem;margin-left:.8125em}
---
.drag-drop-area .separator{font-size:.8125rem;margin-left:.8125em}
---
.restore-progress-container #onstep{text-align:center;margin:0;width:100%}
---
.restore-progress-container #restore_progress{margin:15px 0}
---
#restore_step{padding:2em !important}
---
#restore_step .hndle{margin-bottom:1em;margin-top:0;padding:0;padding-bottom:1em}
---

