public function admin_css() {
	$screen = get_current_screen();
	if ( ! $screen || strpos( $screen->id, 'backwpup' ) === false ) {
		return;
	}

	wp_enqueue_style(
		'backwpup',
		BackWPup::get_plugin_data( 'URL' ) . '/assets/css/main.min.css',
		[],
		BackWPup::get_plugin_data( 'Version' ),
		'screen'
	);
}

